import { describe, expect, it } from "vitest";
import { createSolvedCube, cubeToFacelets } from "./cubie";
import { applyMoves, parseSequence } from "./moves";

/**
 * Expected facelet strings are generated by the authoritative Python engine
 * (`app.cube.cubie.apply_move_names(...).to_facelets()`). Keeping them here
 * guards the frontend cubie model against drifting from the backend solver.
 */
const PARITY_FIXTURES: Array<{ sequence: string; facelets: string }> = [
  {
    sequence: "R U R' U'",
    facelets: "UULUUFUUFRRUBRRURRFFDFFUFFFDDRDDDDDDBLLLLLLLLBRRBBBBBB",
  },
  {
    sequence: "R U R' U' F2 D L2 B'",
    facelets: "UBBDUFDDDLRDLRUDFLRFFBFFRLRUDFUDUFRURBBDLLULBLUFRBRBBL",
  },
  {
    sequence: "F R U' R' U' R U R' F'",
    facelets: "FFUUUURRULLFRRRRRRUUBFFFFFFDDDDDDDDDLBBLLLLLLRUUBBBBBB",
  },
  {
    sequence: "R2 U2 F' L D B2 R' U",
    facelets: "BBLRUURDDBRDLRFUDLFLLDFUDURFBBDDFUUUDBURLRLBRFLRLBFBFF",
  },
];

describe("facelet extraction", () => {
  it("returns the solved string for a fresh cube", () => {
    expect(cubeToFacelets(createSolvedCube())).toBe(
      "UUUUUUUUURRRRRRRRRFFFFFFFFFDDDDDDDDDLLLLLLLLLBBBBBBBBB",
    );
  });

  for (const { sequence, facelets } of PARITY_FIXTURES) {
    it(`matches the backend engine for ${sequence}`, () => {
      const cube = applyMoves(createSolvedCube(), parseSequence(sequence));
      expect(cubeToFacelets(cube)).toBe(facelets);
    });
  }
});
